static final int MAX = 1 << 20;
float[] x = new float[MAX], y = new float[MAX];
float[] vx = new float[MAX], vy = new float[MAX];
int active = 0;
static void step(float[] x, float[] y, float[] vx, float[] vy, int active, float dt) {
    for (int i = 0; i < active; i++) {        // no header, no chase, no boxing
        x[i] += vx[i] * dt;
        y[i] += vy[i] * dt;
    }
}
// deactivate(i): x[i] = x[--active]; y[i] = y[active]; ... (every column in lockstep)

